export const products = [
  { id: 1, name: 'iPhone 15 Pro', brand: 'Apple', category: 'Electronics', size: '256GB', image: '📱' },
  { id: 2, name: 'Samsung Galaxy S24', brand: 'Samsung', category: 'Electronics', size: '128GB', image: '📱' },
  { id: 3, name: 'Nike Air Max', brand: 'Nike', category: 'Footwear', size: 'UK 9', image: '👟' },
  { id: 4, name: 'Adidas Ultraboost', brand: 'Adidas', category: 'Footwear', size: 'UK 10', image: '👟' },
  { id: 5, name: 'Sony WH-1000XM5', brand: 'Sony', category: 'Electronics', size: 'Standard', image: '🎧' },
  { id: 6, name: 'MacBook Pro M3', brand: 'Apple', category: 'Electronics', size: '14-inch', image: '💻' },
  { id: 7, name: 'Levi\'s 501 Jeans', brand: 'Levi\'s', category: 'Clothing', size: '32W 34L', image: '👖' },
  { id: 8, name: 'Nintendo Switch', brand: 'Nintendo', category: 'Gaming', size: 'OLED', image: '🎮' },
];

export const stores = [
  {
    id: 1,
    name: 'TechMart Central',
    location: 'Downtown Plaza',
    distance: 0.8,
    rating: 4.5,
    coordinates: { lat: 27.7172, lng: 85.3240 }
  },
  {
    id: 2,
    name: 'ElectroHub',
    location: 'New Road',
    distance: 1.2,
    rating: 4.3,
    coordinates: { lat: 27.7050, lng: 85.3150 }
  },
  {
    id: 3,
    name: 'MegaStore Express',
    location: 'Durbar Marg',
    distance: 2.5,
    rating: 4.7,
    coordinates: { lat: 27.7100, lng: 85.3200 }
  },
  {
    id: 4,
    name: 'QuickBuy Outlet',
    location: 'Thamel',
    distance: 3.1,
    rating: 4.2,
    coordinates: { lat: 27.7150, lng: 85.3100 }
  },
  {
    id: 5,
    name: 'PrimeMart',
    location: 'Patan',
    distance: 4.5,
    rating: 4.6,
    coordinates: { lat: 27.6800, lng: 85.3250 }
  },
];

export const generateStockData = (productId, storeId) => {
  const baseStock = Math.floor(Math.random() * 50) + 1;
  const isInStock = Math.random() > 0.2;
  const basePrice = productId * 10000 + Math.floor(Math.random() * 5000);

  return {
    inStock: isInStock,
    quantity: isInStock ? baseStock : 0,
    price: basePrice,
    discount: Math.random() > 0.5 ? Math.floor(Math.random() * 20) + 5 : 0,
    lastUpdated: new Date(Date.now() - Math.floor(Math.random() * 3600000)).toISOString(),
    predictedStockDays: isInStock ? Math.floor(baseStock / (Math.random() * 3 + 1)) : 0,
    trending: Math.random() > 0.7
  };
};

export const stockTrends = {
  labels: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'],
  datasets: [
    {
      label: 'Stock Level',
      data: [45, 42, 38, 35, 32, 28, 25],
      borderColor: 'rgb(59, 130, 246)',
      backgroundColor: 'rgba(59, 130, 246, 0.1)',
      tension: 0.4
    },
    {
      label: 'Predicted Demand',
      data: [3, 4, 3, 3, 4, 3, 5],
      borderColor: 'rgb(239, 68, 68)',
      backgroundColor: 'rgba(239, 68, 68, 0.1)',
      tension: 0.4
    }
  ]
};
